Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Model</label>
<div style="display:flex;gap:4px;">
  <button id="btnWave" class="active">Wave (a)</button>
  <button id="btnParticle">Particle (b)</button>
</div>
<label>Time accumulation</label>
<button id="btnAnim">▶ Play</button>
<label>Slit separation d: <span id="dVal">0.80</span></label>
<input type="range" id="slitSlider" min="0.4" max="1.6" step="0.05" value="0.8" />
<label style="margin-top:6px;font-weight:bold;">Demo Steps</label>
<button id="step1">1. Wave interference</button>
<button id="step2">2. Wider slits, tighter fringes</button>
<button id="step3">3. Particle buildup over time</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──
// electron source → SphereGeometry(0.08) gold #d4a017 at (-3.5,0,0)
// barrier → BoxGeometry(0.12,3.2,2.6) grey #8a8a8a at (0,0,0)
// slit lines → BoxGeometry(0.13,0.02,2.6) white at (0,±d/2,0)
// incident arcs → 12 Line semicircles gold centered at source, radii 0.28..3.36
// diffracted arcs → 14 Line semicircles gold per slit, radii 0.3..4.2
// wave screen → PlaneGeometry(2.6,3.2) canvas-texture black+gold fringes at x=4.2
// particle source → same sphere + 2 arrow groups (cylinder+cone) gold
// flying dots → Points yellow between source/barrier and barrier/screens
// 3 particle screens → PlaneGeometry(2.6,3.2) black at x=2.6,4.0,5.4
// screen dots → Points per screen, additive blending, y from cos² distribution
// time arrow → Line + ConeGeometry grey at y=-2.0

const LAMBDA_L = 1.0;
const GOLD = 0xd4a017;
const YELLOW = 0xe0b400;
const GREY = 0x8a8a8a;
const SY = 3.2, SZ = 2.6;

let currentD = 0.8;
let isWaveMode = true;
let animProgress = 0;
let animPlaying = false;

const waveGroup = new THREE.Group();
const particleGroup = new THREE.Group();
scene.add(waveGroup);
scene.add(particleGroup);

function intensity(y, d) { return Math.cos(Math.PI * d * y / LAMBDA_L) ** 2; }

function sampleY(d) {
  for (let i = 0; i < 2000; i++) {
    const y = (Math.random() * 2 - 1) * (SY / 2);
    if (Math.random() < intensity(y, d)) return y;
  }
  return 0;
}

function arcPoints(cx, cy, r, n = 64) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = -Math.PI / 2 + Math.PI * i / n;
    pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0));
  }
  return pts;
}

// ── Wave group ──
const srcGeo = new THREE.SphereGeometry(0.08, 16, 16);
const srcMat = new THREE.MeshBasicMaterial({ color: GOLD });
const srcMesh = new THREE.Mesh(srcGeo, srcMat);
srcMesh.position.set(-3.5, 0, 0);
waveGroup.add(srcMesh);

const barrierGeo = new THREE.BoxGeometry(0.12, SY, SZ);
const barrierMat = new THREE.MeshBasicMaterial({ color: GREY });
const barrierMesh = new THREE.Mesh(barrierGeo, barrierMat);
waveGroup.add(barrierMesh);

const slitMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
let slit1, slit2;
function updateSlits() {
  if (slit1) { waveGroup.remove(slit1); slit1.geometry.dispose(); }
  if (slit2) { waveGroup.remove(slit2); slit2.geometry.dispose(); }
  const g = new THREE.BoxGeometry(0.13, 0.025, SZ);
  slit1 = new THREE.Mesh(g, slitMat); slit1.position.set(0, currentD / 2, 0);
  slit2 = new THREE.Mesh(g.clone(), slitMat); slit2.position.set(0, -currentD / 2, 0);
  waveGroup.add(slit1, slit2);
}
updateSlits();

const arcMat = new THREE.LineBasicMaterial({ color: GOLD, transparent: true, opacity: 0.65 });
for (let i = 1; i <= 12; i++) {
  const r = 0.28 * i;
  const geo = new THREE.BufferGeometry().setFromPoints(arcPoints(-3.5, 0, r));
  waveGroup.add(new THREE.Line(geo, arcMat));
}

let difArcs = [];
function buildDifArcs() {
  difArcs.forEach(l => { waveGroup.remove(l); l.geometry.dispose(); });
  difArcs = [];
  for (let i = 1; i <= 14; i++) {
    const r = 0.3 * i;
    [currentD / 2, -currentD / 2].forEach(sy => {
      const geo = new THREE.BufferGeometry().setFromPoints(arcPoints(0, sy, r));
      const l = new THREE.Line(geo, arcMat);
      waveGroup.add(l);
      difArcs.push(l);
    });
  }
}
buildDifArcs();

// Wave screen with fringe texture
const sCanvas = document.createElement('canvas');
sCanvas.width = 256; sCanvas.height = 256;
const sCtx = sCanvas.getContext('2d');
const sTex = new THREE.CanvasTexture(sCanvas);

function updateScreenTex() {
  const w = 256, h = 256;
  sCtx.fillStyle = '#000'; sCtx.fillRect(0, 0, w, h);
  for (let py = 0; py < h; py++) {
    const y = (1 - py / (h - 1)) * SY - SY / 2;
    const I = intensity(y, currentD);
    sCtx.fillStyle = `rgb(${Math.round(212*I)},${Math.round(184*I)},${Math.round(74*I)})`;
    sCtx.fillRect(0, py, w, 1);
  }
  sTex.needsUpdate = true;
}
updateScreenTex();

const wsGeo = new THREE.PlaneGeometry(SZ, SY);
const wsMat = new THREE.MeshBasicMaterial({ map: sTex, side: THREE.DoubleSide });
const wsMesh = new THREE.Mesh(wsGeo, wsMat);
wsMesh.rotation.y = -Math.PI / 2;
wsMesh.position.set(4.2, 0, 0);
waveGroup.add(wsMesh);

// ── Particle group ──
const pSrc = new THREE.Mesh(srcGeo.clone(), srcMat.clone());
pSrc.position.set(-3.5, 0, 0);
particleGroup.add(pSrc);

function makeArrow(x, y) {
  const g = new THREE.Group();
  const sm = new THREE.MeshBasicMaterial({ color: GOLD });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.45, 8), sm);
  shaft.rotation.z = Math.PI / 2; shaft.position.x = 0.22;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.15, 8), sm);
  head.rotation.z = -Math.PI / 2; head.position.x = 0.5;
  g.add(shaft, head); g.position.set(x, y, 0);
  return g;
}
particleGroup.add(makeArrow(-3.3, 0.35), makeArrow(-3.3, -0.35));

// Flying dots
const dotMat = new THREE.PointsMaterial({ color: YELLOW, size: 0.055, transparent: true, opacity: 0.9 });
function makeDots(n, x0, x1, ySpread, zSpread) {
  const pos = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    pos[i*3] = x0 + Math.random() * (x1 - x0);
    pos[i*3+1] = (Math.random()*2-1) * ySpread;
    pos[i*3+2] = (Math.random()*2-1) * zSpread;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return new THREE.Points(geo, dotMat.clone());
}
particleGroup.add(makeDots(50, -3.4, -0.2, 1.1, 0.9));
particleGroup.add(makeDots(35, 0.3, 2.4, 1.3, 0.9));

// Three screens + dots
const screenXs = [2.6, 4.0, 5.4];
const caps = [0.08, 0.35, 1.0];
const dotsData = [];

screenXs.forEach((sx, si) => {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(SZ, SY), new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide }));
  m.rotation.y = -Math.PI / 2; m.position.set(sx, 0, 0);
  particleGroup.add(m);

  const N = 250;
  const truePos = new Float32Array(N * 3);
  const arrivals = new Float32Array(N);
  const pos = new Float32Array(N * 3);
  for (let i = 0; i < N; i++) {
    truePos[i*3] = sx + 0.06;
    truePos[i*3+1] = sampleY(currentD);
    truePos[i*3+2] = (Math.random()*2-1) * (SZ/2 - 0.1);
    pos[i*3] = 0; pos[i*3+1] = -999; pos[i*3+2] = 0;
    arrivals[i] = Math.random() * caps[si];
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  const pm = new THREE.PointsMaterial({ color: YELLOW, size: 0.05, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending });
  const pts = new THREE.Points(geo, pm);
  particleGroup.add(pts);
  dotsData.push({ truePos, arrivals, pts, N, sx });
});

// Time arrow
const taMat = new THREE.LineBasicMaterial({ color: 0x555555 });
const taGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(2.4,-2.1,0), new THREE.Vector3(5.8,-2.1,0)]);
particleGroup.add(new THREE.Line(taGeo, taMat));
const taHead = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.18, 8), new THREE.MeshBasicMaterial({ color: 0x555555 }));
taHead.rotation.z = -Math.PI/2; taHead.position.set(5.9,-2.1,0);
particleGroup.add(taHead);

// ── Update logic ──
function updateDotsVis() {
  dotsData.forEach(d => {
    const attr = d.pts.geometry.attributes.position;
    for (let i = 0; i < d.N; i++) {
      if (animProgress >= d.arrivals[i]) {
        attr.setXYZ(i, d.truePos[i*3], d.truePos[i*3+1], d.truePos[i*3+2]);
      } else { attr.setXYZ(i, 0, -999, 0); }
    }
    attr.needsUpdate = true;
  });
}

function rebuildAll() {
  updateSlits(); buildDifArcs(); updateScreenTex();
  dotsData.forEach(d => {
    for (let i = 0; i < d.N; i++) {
      d.truePos[i*3+1] = sampleY(currentD);
      d.truePos[i*3+2] = (Math.random()*2-1)*(SZ/2-0.1);
    }
  });
  updateDotsVis();
}

function setMode(wave) {
  isWaveMode = wave;
  waveGroup.visible = wave;
  particleGroup.visible = !wave;
  document.getElementById('btnWave').classList.toggle('active', wave);
  document.getElementById('btnParticle').classList.toggle('active', !wave);
  lblA.div.style.display = wave ? '' : 'none';
  lblB.div.style.display = wave ? 'none' : '';
  lblTime.div.style.display = wave ? 'none' : '';
}

// Animation
let animStart = 0;
const ANIM_DUR = 6000;
function animTick() {
  if (!animPlaying) return;
  animProgress = ((performance.now() - animStart) % ANIM_DUR) / ANIM_DUR;
  updateDotsVis();
  requestAnimationFrame(animTick);
}
function toggleAnim() {
  animPlaying = !animPlaying;
  document.getElementById('btnAnim').textContent = animPlaying ? '⏸ Pause' : '▶ Play';
  if (animPlaying) { animStart = performance.now() - animProgress * ANIM_DUR; requestAnimationFrame(animTick); }
}

// ── UI wiring ──
document.getElementById('btnWave').addEventListener('click', () => setMode(true));
document.getElementById('btnParticle').addEventListener('click', () => setMode(false));
document.getElementById('btnAnim').addEventListener('click', toggleAnim);
document.getElementById('slitSlider').addEventListener('input', (e) => {
  currentD = parseFloat(e.target.value);
  document.getElementById('dVal').textContent = currentD.toFixed(2);
  rebuildAll();
});

// Demo steps
function goToStep(n) {
  if (n === 1) { setMode(true); currentD = 0.8; document.getElementById('slitSlider').value = 0.8; document.getElementById('dVal').textContent = '0.80'; rebuildAll(); }
  if (n === 2) { setMode(true); currentD = 1.4; document.getElementById('slitSlider').value = 1.4; document.getElementById('dVal').textContent = '1.40'; rebuildAll(); }
  if (n === 3) { setMode(false); currentD = 0.8; document.getElementById('slitSlider').value = 0.8; document.getElementById('dVal').textContent = '0.80'; rebuildAll(); if (!animPlaying) toggleAnim(); }
}
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('step3').addEventListener('click', () => goToStep(3));

// ── Camera ──
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.7 });

// ── Labels ──
const lblSrc = addLabel('Electron<br>source', new THREE.Vector3(-3.5, 0.6, 0), { fontSize: '12px' });
const lblA = addLabel('(a)', new THREE.Vector3(0.5, -2.3, 0), { fontSize: '14px', bold: true });
const lblB = addLabel('(b)', new THREE.Vector3(1.0, -2.6, 0), { fontSize: '14px', bold: true });
const lblTime = addLabel('<b>Time</b>', new THREE.Vector3(4.1, -2.4, 0), { fontSize: '12px' });
lblB.div.style.display = 'none';
lblTime.div.style.display = 'none';

// Interactive explanations
registerInteractive(barrierMesh, { title: 'Double-slit barrier', body: 'Two narrow slits separated by distance d. Each slit acts as a new wave source (Huygens principle), producing circular wavefronts that overlap and interfere.', tooltip: 'Double-slit barrier' });
registerInteractive(wsMesh, { title: 'Interference pattern', body: 'Bright fringes occur where waves from both slits arrive in phase (constructive interference). Fringe spacing = λL/d, so increasing d squeezes fringes together.', tooltip: 'Detection screen — interference fringes' });
registerInteractive(srcMesh, { title: 'Electron source', body: 'Emits electrons one at a time. In the wave picture, each electron is described by a wavefunction that passes through both slits simultaneously.', tooltip: 'Electron source' });
// @FIGURE_CODE_END

