function intensity(y, d) { return Math.cos(Math.PI * d * y / LAMBDA_L) ** 2; }

function sampleY(d) {
  for (let i = 0; i < 2000; i++) {
    const y = (Math.random() * 2 - 1) * (SY / 2);
    if (Math.random() < intensity(y, d)) return y;
  }
  return 0;
}

function arcPoints(cx, cy, r, n = 64) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = -Math.PI / 2 + Math.PI * i / n;
    pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0));
  }
  return pts;
}

