// Animation loop (driven from the main scaffold RAF via a flag, but we use our own rAF)
let animStart = 0;
const ANIM_DUR = 6000;
function animTick() {
  if (!animPlaying) return;
  animProgress = ((performance.now() - animStart) % ANIM_DUR) / ANIM_DUR;
