registerInteractive(barrierMesh, { title: 'Double-slit barrier', body: 'Two narrow slits separated by distance d. By Huygens’ principle each slit becomes a new source of circular wavefronts; the two families overlap and interfere beyond the barrier.', tooltip: 'Double-slit barrier' });
