// ── Element specs (world space: +X beam/right, +Y up, +Z receding tilt) ──
// electron source   → SphereGeometry(0.09) gold #d4a017 at (-3.5,0,0)
// barrier           → BoxGeometry(0.12,3.2,2.6) grey #8a8a8a at (0,0,0)
// slit gaps (x2)    → BoxGeometry(0.14,0.03,2.6) white on barrier face at y=±d/2
// incident arcs     → ~10 Line right-semicircles gold centered at source
// diffracted arcs   → ~12 Line right-semicircles gold per slit (two families)
// wave screen       → PlaneGeometry(2.6,3.2) canvas-texture black+gold fringes at x=4.2
// particle arrows   → 2 groups (cylinder+cone) gold rightward at source
// flying dots       → Points yellow between source/barrier and barrier/screens
// 3 particle screens→ PlaneGeometry(2.6,3.2) black at x=2.6,4.0,5.4
// screen dots       → Points per screen (additive), y from cos² distribution, drawRange reveal
// time arrow        → Line + ConeGeometry grey at y=-2.1 spanning x[2.4,5.8]

const LAMBDA_L = 1.0;
const GOLD = 0xd4a017, YELLOW = 0xe0b400, GREY = 0x8a8a8a;
const SY = 3.2, SZ = 2.6;

let currentD = 0.8;
let isWaveMode = true;
let animProgress = 1.0;     // start full so particle view matches the printed figure
let animPlaying = false;

const waveGroup = new THREE.Group();
const particleGroup = new THREE.Group();
scene.add(waveGroup);
scene.add(particleGroup);

function intensity(y, d) { const c = Math.cos(Math.PI * d * y / LAMBDA_L); return c * c; }
function sampleY(d) {
  for (let i = 0; i < 4000; i++) {
    const y = (Math.random() * 2 - 1) * (SY / 2);
    if (Math.random() < intensity(y, d)) return y;
  }
  return 0;
}
function arcPoints(cx, cy, r, n = 56) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = -Math.PI / 2 + Math.PI * i / n;
    pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0));
  }
  return pts;
}

// ── Wave group ──
const srcMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.09, 16, 16),
  new THREE.MeshBasicMaterial({ color: GOLD }));
srcMesh.position.set(-3.5, 0, 0);
waveGroup.add(srcMesh);

const barrierMesh = new THREE.Mesh(
  new THREE.BoxGeometry(0.12, SY, SZ),
  new THREE.MeshBasicMaterial({ color: GREY }));
waveGroup.add(barrierMesh);

const slitMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
let slit1 = null, slit2 = null;
function updateSlits() {
  if (slit1) { waveGroup.remove(slit1); slit1.geometry.dispose(); }
  if (slit2) { waveGroup.remove(slit2); slit2.geometry.dispose(); }
  const g = new THREE.BoxGeometry(0.14, 0.03, SZ);
  slit1 = new THREE.Mesh(g, slitMat); slit1.position.set(0.001, currentD / 2, 0);
  slit2 = new THREE.Mesh(g.clone(), slitMat); slit2.position.set(0.001, -currentD / 2, 0);
  waveGroup.add(slit1, slit2);
}
updateSlits();

const arcMat = new THREE.LineBasicMaterial({ color: GOLD, transparent: true, opacity: 0.7 });
for (let i = 1; i <= 10; i++) {
  const r = 0.32 * i;
  waveGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(arcPoints(-3.5, 0, r)), arcMat));
}

let difArcs = [];
function buildDifArcs() {
  difArcs.forEach(l => { waveGroup.remove(l); l.geometry.dispose(); });
  difArcs = [];
  for (let i = 1; i <= 12; i++) {
    const r = 0.34 * i;
    [currentD / 2, -currentD / 2].forEach(sy => {
      const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(arcPoints(0, sy, r)), arcMat);
      waveGroup.add(l); difArcs.push(l);
    });
  }
}
buildDifArcs();

// Wave detection screen with fringe texture
const sCanvas = document.createElement('canvas');
sCanvas.width = 64; sCanvas.height = 256;
const sCtx = sCanvas.getContext('2d');
const sTex = new THREE.CanvasTexture(sCanvas);
sTex.colorSpace = THREE.SRGBColorSpace;
function updateScreenTex() {
  const w = 64, h = 256;
  sCtx.fillStyle = '#000'; sCtx.fillRect(0, 0, w, h);
  for (let py = 0; py < h; py++) {
    const y = (1 - py / (h - 1)) * SY - SY / 2;
    const I = intensity(y, currentD);
    const v = Math.round(255 * I);
    sCtx.fillStyle = `rgb(${Math.round(212 * I)},${Math.round(184 * I)},${Math.round(74 * I)})`;
    sCtx.fillRect(0, py, w, 1);
  }
  sTex.needsUpdate = true;
}
updateScreenTex();

const wsMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(SZ, SY),
  new THREE.MeshBasicMaterial({ map: sTex, side: THREE.DoubleSide }));
wsMesh.rotation.y = -Math.PI / 2;
wsMesh.position.set(4.2, 0, 0);
waveGroup.add(wsMesh);

// ── Particle group ──
const pSrc = new THREE.Mesh(new THREE.SphereGeometry(0.09, 16, 16), new THREE.MeshBasicMaterial({ color: GOLD }));
pSrc.position.set(-3.5, 0, 0);
particleGroup.add(pSrc);

function makeArrow(x, y) {
  const g = new THREE.Group();
  const sm = new THREE.MeshBasicMaterial({ color: GOLD });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.5, 8), sm);
  shaft.rotation.z = Math.PI / 2; shaft.position.x = 0.25;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 8), sm);
  head.rotation.z = -Math.PI / 2; head.position.x = 0.58;
  g.add(shaft, head); g.position.set(x, y, 0);
  return g;
}
particleGroup.add(makeArrow(-3.35, 0.4), makeArrow(-3.35, -0.4));

// Flying dot clouds (static, within bounds)
function makeDots(n, x0, x1, ySpread, zSpread) {
  const pos = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    pos[i * 3] = x0 + Math.random() * (x1 - x0);
    pos[i * 3 + 1] = (Math.random() * 2 - 1) * ySpread;
    pos[i * 3 + 2] = (Math.random() * 2 - 1) * zSpread;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return new THREE.Points(geo, new THREE.PointsMaterial({ color: YELLOW, size: 0.06, transparent: true, opacity: 0.85 }));
}
particleGroup.add(makeDots(60, -3.4, -0.15, 1.1, 0.9));
particleGroup.add(makeDots(40, 0.3, 2.3, 1.3, 0.9));

// Three detection screens + accumulating dots (drawRange reveal, no out-of-bounds coords)
const screenXs = [2.6, 4.0, 5.4];
const caps = [0.08, 0.35, 1.0];
const BASE_N = 260;
const dotsData = [];

screenXs.forEach((sx, si) => {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(SZ, SY),
    new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide }));
  m.rotation.y = -Math.PI / 2; m.position.set(sx, 0, 0);
  particleGroup.add(m);

  const M = Math.max(8, Math.round(BASE_N * caps[si]));
  // build (arrival, y, z) then sort by arrival so setDrawRange reveals in time order
  const items = [];
  for (let i = 0; i < M; i++) {
    items.push({ a: Math.random(), y: sampleY(currentD), z: (Math.random() * 2 - 1) * (SZ / 2 - 0.12) });
  }
  items.sort((p, q) => p.a - q.a);
  const pos = new Float32Array(M * 3);
  for (let i = 0; i < M; i++) { pos[i * 3] = sx + 0.06; pos[i * 3 + 1] = items[i].y; pos[i * 3 + 2] = items[i].z; }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setDrawRange(0, 0);
  const pts = new THREE.Points(geo, new THREE.PointsMaterial({
    color: YELLOW, size: 0.055, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
  particleGroup.add(pts);
  dotsData.push({ pts, M, sx });
});

// Time arrow
const taMat = new THREE.LineBasicMaterial({ color: 0x555555 });
particleGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
  [new THREE.Vector3(2.4, -2.1, 0), new THREE.Vector3(5.8, -2.1, 0)]), taMat));
const taHead = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.2, 8), new THREE.MeshBasicMaterial({ color: 0x555555 }));
taHead.rotation.z = -Math.PI / 2; taHead.position.set(5.92, -2.1, 0);
particleGroup.add(taHead);

// ── Reveal / rebuild logic ──
function updateReveal() {
  dotsData.forEach(d => { d.pts.geometry.setDrawRange(0, Math.round(d.M * Math.min(1, Math.max(0, animProgress)))); });
}
function rebuildAll() {
  updateSlits(); buildDifArcs(); updateScreenTex();
  dotsData.forEach(d => {
    const attr = d.pts.geometry.attributes.position;
    for (let i = 0; i < d.M; i++) {
      attr.setXYZ(i, d.sx + 0.06, sampleY(currentD), (Math.random() * 2 - 1) * (SZ / 2 - 0.12));
    }
    attr.needsUpdate = true;
  });
  updateReveal();
}

